import { DayPickerBase, DaySelectionMode, Matcher } from 'react-day-picker';
import { LegendBase, LegendProps } from './components/Legend/Legend.types';

export type CalendarProps = {
  numberOfMonths?: 1 | 2;
  customLocale?: 'pt' | 'en' | 'es';
  mode?: CalendarSelectionMode;
  legend?: CalendarLegend;
  onChange?: (selection: Matcher | Matcher[] | undefined) => void;
  hightlightedDates?: HightlightedDateBase[];
} & Omit<
  DayPickerBase,
  'numberOfMonths' | 'showOutsideDays' | 'selected' | 'modifiersClassNames' | 'formatters'
>;

export interface CalendarRef extends HTMLDivElement {
  clearSelection: () => void;
  changeSelection: (value: Matcher | Matcher[]) => void;
}

export type CalendarSelectionMode = Exclude<DaySelectionMode, 'default'>;

export type CalendarLegend = Omit<LegendProps, 'captions'>;

export type HightlightedDateBase = {
  dates: Date[];
} & LegendBase;
